	const firstDay = Math.floor(timestamp / DAY_MS);
	const horizon = timestamp + 8 * DAY_MS;
	let next = Number.POSITIVE_INFINITY;
	for (let offset = 0; offset <= 8; offset++) {
		const day = firstDay + offset;
		const weekday = (((day + 4) % 7) + 7) % 7;
