	const arm = (ctx: ExtensionContext): void => {
		context = ctx;
		edgeTimer && ctx.clearTimer(edgeTimer);
		heartbeat && ctx.clearTimer(heartbeat);
		const schedule = (): void => {
			const now = Date.now();
			const next = nextTransition(windows, now);
			// +50ms so the timer lands just inside the new period rather than 1ms early.
			const delay = next === undefined ? HEARTBEAT_MS : Math.max(1, Math.min(next - now + 50, 7 * DAY_MS));
			edgeTimer = ctx.setTimeout(() => {
				if (windows.length > 0) manual = undefined;
				apply(Date.now(), "edge");
				schedule();
			}, delay);
		};
