const NOTIFY_COOLDOWN_MS = 60_000;
const WEEKDAY_NAMES = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"] as const;

/** One recurring peak-pricing window, expressed in UTC minute-of-day. */
interface PeakWindow {
