/**
 * Extension factory. `agentPauseGate` is a process-global singleton shared with
 * the TUI `/pause` command, main agents, in-process subagents, and advisors.
 */
export default function deepseekPeakGate(pi: ExtensionAPI) {
	let { windows, enabled, source } = loadWindows();
	let backstop = process.env.OMP_PEAK_GATE_NO_BACKSTOP !== "1";
	/** True only while this extension is the one holding the gate. */
	let holding = false;
	/** Manual override applied until the next window boundary. */
	let manual: "pause" | "resume" | undefined;
	let context: ExtensionContext | undefined;
	let edgeTimer: ReturnType<ExtensionContext["setTimeout"]> | undefined;
	let heartbeat: ReturnType<ExtensionContext["setInterval"]> | undefined;
	let lastNotifyAt = 0;

	const shouldPause = (now: number): boolean => {
		if (!enabled) return false;
		if (manual === "pause") return true;
		if (manual === "resume") return false;
		return isPeak(windows, now);
	};

	const statusText = (now: number): string | undefined => {
		if (!agentPauseGate.paused && !holding) return undefined;
		const next = nextTransition(windows, now);
		const until = next === undefined ? "" : ` until ${new Date(next).toISOString().slice(11, 16)} UTC`;
		return `⏸ peak-gate${until}`;
	};

	/** Reconcile the gate with the clock. Idempotent; safe to call at any time. */
	const apply = (now: number, reason: "timer" | "edge" | "startup" | "command" | "heartbeat"): void => {
		const want = shouldPause(now);
		if (want && !agentPauseGate.paused) {
			// pause() reports false when someone else (the user, /pause) holds it.
			holding = agentPauseGate.pause();
		} else if (!want && holding && agentPauseGate.paused) {
			agentPauseGate.resume();
			holding = false;
		} else if (!want) {
			holding = false;
		}
		context?.ui.setStatus("peak-gate", holding ? (statusText(now) ?? "⏸ peak-gate") : undefined);
		if (reason === "command") return;
		if (want && holding && now - lastNotifyAt > NOTIFY_COOLDOWN_MS) {
			lastNotifyAt = now;
			const next = nextTransition(windows, now);
			const until = next === undefined ? "" : `; next release ${new Date(next).toISOString().replace("T", " ").slice(0, 16)} UTC`;
			context?.ui.notify(`DeepSeek peak window (${describeWindows(windows)}): LLM calls paused${until}`, "info");
		} else if (!want && reason === "edge") {
			context?.ui.notify("Peak window closed: LLM calls resumed", "info");
		}
	};

	/** Arm the precise edge timer plus the heartbeat re-derivation. */
	const arm = (ctx: ExtensionContext): void => {
		context = ctx;
		edgeTimer && ctx.clearTimer(edgeTimer);
		heartbeat && ctx.clearTimer(heartbeat);
		const schedule = (): void => {
			const now = Date.now();
			const next = nextTransition(windows, now);
			// +50ms so the timer lands just inside the new period rather than 1ms early.
			const delay = next === undefined ? HEARTBEAT_MS : Math.max(1, Math.min(next - now + 50, 7 * DAY_MS));
			edgeTimer = ctx.setTimeout(() => {
				if (windows.length > 0) manual = undefined;
				apply(Date.now(), "edge");
				schedule();
			}, delay);
		};
		schedule();
		heartbeat = ctx.setInterval(() => apply(Date.now(), "heartbeat"), HEARTBEAT_MS);
		apply(Date.now(), "startup");
	};

	pi.on("session_start", (_event, ctx) => arm(ctx));

	// Backstop: any request that still reaches the wire during a window (a
	// side turn, advisor, compaction, or title call that did not park on the
	// gate) is aborted before dispatch, so it is never billed.
	pi.on("before_provider_request", (_event, ctx) => {
		if (!backstop || !enabled) return;
		if (!shouldPause(Date.now())) return;
		ctx.abort();
		if (Date.now() - lastNotifyAt > NOTIFY_COOLDOWN_MS) {
			lastNotifyAt = Date.now();
			ctx.ui.notify(`Refused a provider request during the DeepSeek peak window (${describeWindows(windows)})`, "warning");
		}
	});

	pi.registerCommand("peak-gate", {
		description: "Show or override the DeepSeek peak-hour LLM gate",
		handler: async (args, ctx) => {
			const action = args.trim().split(/\s+/)[0] || "status";
			const now = Date.now();
			switch (action) {
				case "pause":
					manual = "pause";
					apply(now, "command");
					ctx.ui.notify(`Peak gate held open: LLM calls paused (${describeWindows(windows)})`, "info");
					break;
				case "resume":
					manual = "resume";
					if (holding && agentPauseGate.paused) {
						agentPauseGate.resume();
						holding = false;
					}
					apply(now, "command");
					ctx.ui.notify("Peak gate released until the next window boundary", "info");
					break;
				case "reload": {
					const loaded = loadWindows();
					windows = loaded.windows;
					enabled = loaded.enabled;
					source = loaded.source;
					manual = undefined;
					arm(ctx);
					ctx.ui.notify(`Peak gate reloaded from ${source}: ${describeWindows(windows)}`, "info");
					break;
				}
				default: {
					const next = nextTransition(windows, now);
					const lines = [
						`peak gate: ${enabled ? "enabled" : "disabled (OMP_PEAK_GATE=off or config)"}`,
						`windows: ${describeWindows(windows)} (${source})`,
						`now: ${isPeak(windows, now) ? "PEAK - LLM calls paused" : "off-peak"}`,
						`gate: ${agentPauseGate.paused ? (holding ? "engaged by peak-gate" : "engaged elsewhere (/pause)") : "open"}`,
						`next boundary: ${next === undefined ? "none" : new Date(next).toISOString().replace("T", " ").slice(0, 16) + " UTC"}`,
					];
					ctx.ui.notify(lines.join("\n"), "info");
					break;
				}
			}
		},
	});
}

