				windows = entries.map(parseWindow).filter((w): w is PeakWindow => !!w);
				source = "OMP_PEAK_GATE_WINDOWS";
			}
		} catch (error) {
			console.error(`[peak-gate] ignoring malformed OMP_PEAK_GATE_WINDOWS: ${String(error)}`);
		}
	} else {
