					const entries: unknown[] = parsed.windows;
					windows = entries.map(parseWindow).filter((w): w is PeakWindow => !!w);
					source = CONFIG_PATH;
				}
			}
		} catch {
			// No config file (or unreadable/invalid JSON): keep the built-in schedule.
		}
	}
	return { windows, enabled, source };
}

