	const arm = (ctx: ExtensionContext): void => {
…
		apply(Date.now(), "startup");
	};

	pi.on("session_start", (_event, ctx) => arm(ctx));

	// Backstop: any request that still reaches the wire during a window (a
	// side turn, advisor, compaction, or title call that did not park on the
	// gate) is aborted before dispatch, so it is never billed.
	pi.on("before_provider_request", (_event, ctx) => {
		if (!backstop || !enabled) return;
		if (!shouldPause(Date.now())) return;
		ctx.abort();
		if (Date.now() - lastNotifyAt > NOTIFY_COOLDOWN_MS) {
			lastNotifyAt = Date.now();
			ctx.ui.notify(`Refused a provider request during the DeepSeek peak window (${describeWindows(windows)})`, "warning");
		}
	});

	pi.registerCommand("peak-gate", {
		description: "Show or override the DeepSeek peak-hour LLM gate",
		handler: async (args, ctx) => {
			const action = args.trim().split(/\s+/)[0] || "status";
			const now = Date.now();
			switch (action) {
				case "pause":
					manual = "pause";
					apply(now, "command");
					ctx.ui.notify(`Peak gate held open: LLM calls paused (${describeWindows(windows)})`, "info");
					break;
				case "resume":
					manual = "resume";
					if (holding && agentPauseGate.paused) {
						agentPauseGate.resume();
						holding = false;
					}
					apply(now, "command");
					ctx.ui.notify("Peak gate released until the next window boundary", "info");
					break;
				case "reload": {
					const loaded = loadWindows();
					windows = loaded.windows;
					enabled = loaded.enabled;
					source = loaded.source;
					manual = undefined;
					arm(ctx);
					ctx.ui.notify(`Peak gate reloaded from ${source}: ${describeWindows(windows)}`, "info");
					break;
				}
				default: {
					const next = nextTransition(windows, now);
					const lines = [
						`peak gate: ${enabled ? "enabled" : "disabled (OMP_PEAK_GATE=off or config)"}`,
						`windows: ${describeWindows(windows)} (${source})`,
						`now: ${isPeak(windows, now) ? "PEAK - LLM calls paused" : "off-peak"}`,
						`gate: ${agentPauseGate.paused ? (holding ? "engaged by peak-gate" : "engaged elsewhere (/pause)") : "open"}`,
						`next boundary: ${next === undefined ? "none" : new Date(next).toISOString().replace("T", " ").slice(0, 16) + " UTC"}`,
					];
					ctx.ui.notify(lines.join("\n"), "info");
					break;
				}
			}
		},
	});
}

