	const want = shouldPause(now);
	if (want && !agentPauseGate.paused) {
		// pause() reports false when someone else (the user, /pause) holds it.
		holding = agentPauseGate.pause();
	} else if (!want && holding && agentPauseGate.paused) {
		agentPauseGate.resume();
		holding = false;
	} else if (!want) {
		holding = false;
	}
	context?.ui.setStatus("peak-gate", holding ? (statusText(now) ?? "⏸ peak-gate") : undefined);
	if (reason === "command") return;
	if (want && holding && now - lastNotifyAt > NOTIFY_COOLDOWN_MS) {
		lastNotifyAt = now;
		const next = nextTransition(windows, now);
		const until = next === undefined ? "" : `; next release ${new Date(next).toISOString().replace("T", " ").slice(0, 16)} UTC`;
		context?.ui.notify(`DeepSeek peak window (${describeWindows(windows)}): LLM calls paused${until}`, "info");
	} else if (!want && reason === "edge") {
		context?.ui.notify("Peak window closed: LLM calls resumed", "info");
	}
};

/** Arm the precise edge timer plus the heartbeat re-derivation. */
const arm = (ctx: ExtensionContext): void => {
	context = ctx;
	edgeTimer && ctx.clearTimer(edgeTimer);
	heartbeat && ctx.clearTimer(heartbeat);
	const schedule = (): void => {
		const now = Date.now();
		const next = nextTransition(windows, now);
		// +50ms so the timer lands just inside the new period rather than 1ms early.
		const delay = next === undefined ? HEARTBEAT_MS : Math.max(1, Math.min(next - now + 50, 7 * DAY_MS));
		edgeTimer = ctx.setTimeout(() => {
			if (windows.length > 0) manual = undefined;
			apply(Date.now(), "edge");
			schedule();
		}, delay);
	};
	schedule();
	heartbeat = ctx.setInterval(() => apply(Date.now(), "heartbeat"), HEARTBEAT_MS);
	apply(Date.now(), "startup");
};

