/** Minimal OpenAI-compatible SSE mock; logs every chat completion request to requests.log. */
import { appendFileSync } from "node:fs";

const LOG = "/tmp/peak-e2e/requests.log";

Bun.serve({
	port: 8765,
	hostname: "127.0.0.1",
	async fetch(request) {
		const url = new URL(request.url);
		if (url.pathname.endsWith("/models")) {
			return Response.json({ object: "list", data: [{ id: "echo", object: "model" }] });
		}
		if (!url.pathname.endsWith("/chat/completions")) return new Response("not found", { status: 404 });
		const body = await request.json();
		appendFileSync(LOG, `${new Date().toISOString()} ${JSON.stringify(body.model)} stream=${body.stream ?? false}\n`);

		const chunk = (payload: unknown) => `data: ${JSON.stringify(payload)}\n\n`;
		const base = { id: "chatcmpl-mock", object: "chat.completion.chunk", created: Math.floor(Date.now() / 1000), model: "echo" };
		if (body.stream === false) {
			return Response.json({
				...base,
				object: "chat.completion",
				choices: [{ index: 0, message: { role: "assistant", content: "pong" }, finish_reason: "stop" }],
				usage: { prompt_tokens: 5, completion_tokens: 1, total_tokens: 6 },
			});
		}
		const encoder = new TextEncoder();
		const stream = new ReadableStream({
			start(controller) {
				controller.enqueue(encoder.encode(chunk({ ...base, choices: [{ index: 0, delta: { role: "assistant", content: "" } }] })));
				controller.enqueue(encoder.encode(chunk({ ...base, choices: [{ index: 0, delta: { content: "pong" } }] })));
				controller.enqueue(
					encoder.encode(
						chunk({
							...base,
							choices: [{ index: 0, delta: {}, finish_reason: "stop" }],
							usage: { prompt_tokens: 5, completion_tokens: 1, total_tokens: 6 },
						}),
					),
				);
				controller.enqueue(encoder.encode("data: [DONE]\n\n"));
				controller.close();
			},
		});
		return new Response(stream, { headers: { "content-type": "text/event-stream" } });
	},
});
console.log("mock listening on 8765");

