/** Diagnostic probe: where does the first provider request sit relative to session_start and the pause gate? */
import { appendFileSync } from "node:fs";
import { agentPauseGate } from "@oh-my-pi/pi-agent-core";
import type { ExtensionAPI } from "@oh-my-pi/pi-coding-agent";

const LOG = "/tmp/peak-e2e/gate.log";
const log = (message: string) => appendFileSync(LOG, `${new Date().toISOString()} ${message}\n`);

log(`load: gate.paused=${agentPauseGate.paused}`);

export default function probe(pi: ExtensionAPI) {
	pi.on("session_start", (_event, ctx) => {
		log(`session_start: before pause gate.paused=${agentPauseGate.paused}`);
		const engaged = agentPauseGate.pause();
		log(`session_start: pause() returned ${engaged}; gate.paused=${agentPauseGate.paused}`);
		ctx.setInterval(() => log(`tick: gate.paused=${agentPauseGate.paused}`), 2000);
		ctx.setTimeout(() => {
			log("timer 3s: resuming probe pause");
			agentPauseGate.resume();
		}, 3000);
	});

	pi.on("before_provider_request", () => {
		log(`before_provider_request: gate.paused=${agentPauseGate.paused}`);
	});

	pi.on("agent_start", () => log("agent_start"));
	pi.on("turn_start", () => log("turn_start"));
	pi.on("message_start", () => log("message_start"));
	pi.on("session_stop", () => log("session_stop"));
	pi.on("session_shutdown", () => log("session_shutdown"));
}

