function utcParts(timestamp: number): { weekday: number; minute: number } {
	const day = Math.floor(timestamp / DAY_MS);
	return {
		// Unix epoch was a Thursday, so day 0 is weekday 4.
		weekday: (((day + 4) % 7) + 7) % 7,
		minute: Math.floor((timestamp - day * DAY_MS) / MINUTE_MS),
	};
