/** Listen-only probe: timeline of agent events plus the gate state, no pause of its own. */
import { appendFileSync } from "node:fs";
import { agentPauseGate } from "@oh-my-pi/pi-agent-core";
import type { ExtensionAPI } from "@oh-my-pi/pi-coding-agent";

const LOG = "/tmp/peak-e2e/probe.log";
const log = (message: string) => appendFileSync(LOG, `${new Date().toISOString()} ${message}\n`);

export default function probe(pi: ExtensionAPI) {
	pi.on("session_start", (_event, ctx) => {
		log("session_start");
		ctx.setInterval(() => log(`tick gate.paused=${agentPauseGate.paused}`), 1000);
	});
	pi.on("agent_start", () => log("agent_start"));
	pi.on("turn_start", () => log("turn_start"));
	pi.on("message_start", event => log(`message_start role=${event.message.role}`));
	pi.on("message_end", event => log(`message_end role=${event.message.role} stopReason=${event.message.stopReason ?? "-"}`));
	pi.on("agent_end", () => log("agent_end"));
	pi.on("auto_retry_start", () => log("auto_retry_start"));
	pi.on("auto_retry_end", () => log("auto_retry_end"));
	pi.on("session_stop", event => log(`session_stop decision=${JSON.stringify(event)}`));
	pi.on("session_shutdown", () => log("session_shutdown"));
	pi.on("before_provider_request", () => log(`before_provider_request gate.paused=${agentPauseGate.paused}`));
}

