/** Probe: pause the gate and hold a referenced timer to see whether the parked run survives in print mode. */
import { appendFileSync } from "node:fs";
import { agentPauseGate } from "@oh-my-pi/pi-agent-core";
import type { ExtensionAPI } from "@oh-my-pi/pi-coding-agent";

const LOG = "/tmp/peak-e2e/probe3.log";
const log = (message: string) => appendFileSync(LOG, `${new Date().toISOString()} ${message}\n`);

export default function probe(pi: ExtensionAPI) {
	pi.on("session_start", (_event, ctx) => {
		log(`session_start; paused=${agentPauseGate.pause()}`);
		// Referenced (not ctx-managed) interval: keeps the event loop alive while parked.
		setInterval(() => log(`tick gate.paused=${agentPauseGate.paused}`), 2000);
		ctx.setTimeout(() => {
			log("resume at +20s");
			agentPauseGate.resume();
		}, 20_000);
	});
	pi.on("before_provider_request", () => log(`before_provider_request gate.paused=${agentPauseGate.paused}`));
	pi.on("message_end", event => log(`message_end stopReason=${event.message.stopReason ?? "-"}`));
	pi.on("session_shutdown", () => log("session_shutdown"));
}

