	if (process.env.OMP_PEAK_GATE_KEEPALIVE === "0") return;
	if (engaged && keepalive === undefined) {
		keepalive = setInterval(() => {}, 15_000);
	} else if (!engaged && keepalive !== undefined) {
		clearInterval(keepalive);
		keepalive = undefined;
	}
};

