	// turn, advisor, compaction, or title call that did not park on the gate) is
	// aborted before dispatch, so it is never billed.
	pi.on("before_provider_request", (_event, ctx) => {
		if (!backstop || !enabled) return;
		const now = Date.now();
		if (!shouldPause(now)) return;
		debug(`backstop: refusing provider request at ${utcLabel(now)}`);
		ctx.abort();
		if (now - lastNotifyAt > NOTIFY_COOLDOWN_MS) {
			lastNotifyAt = now;
			ctx.ui.notify(`Refused a provider request during the DeepSeek peak window (${describeWindows(windows)})`, "warning");
