/** Probe: does a side turn (`ctx.runEphemeralTurn`, which bypasses the agent-loop gate) get refused during a window? */
import { appendFileSync } from "node:fs";
import type { ExtensionAPI } from "@oh-my-pi/pi-coding-agent";

const LOG = "/tmp/peak-e2e/probe4.log";
const log = (message: string) => appendFileSync(LOG, `${new Date().toISOString()} ${message}\n`);

export default function probe(pi: ExtensionAPI) {
	pi.on("session_start", async (_event, ctx) => {
		if (!ctx.runEphemeralTurn) {
			log("no runEphemeralTurn");
			return;
		}
		const controller = new AbortController();
		try {
			const result = await ctx.runEphemeralTurn({
				promptText: "say side",
				tools: false,
				maxTokens: 64,
				signal: controller.signal,
			});
			log(`side turn completed: ${JSON.stringify(result.replyText)}`);
		} catch (error) {
			log(`side turn rejected: ${String(error)}`);
		}
	});
}

